26	// NewClient creates a new authenticated API client with an explicit bearer token.
27	func NewClient(token string) *Client {
28		return &Client{
29			httpClient: &http.Client{
30				Transport: &bearerTransport{
31					token: token,
32					base:  http.DefaultTransport,
33				},
34			},
