39	// bearerTransport is an http.RoundTripper that injects the Authorization header.
40	type bearerTransport struct {
41		token string
42		base  http.RoundTripper
43	}
44	
45	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
46		// Clone the request to avoid mutating the caller's request.
47		r := req.Clone(req.Context())
48		r.Header.Set("Authorization", "Bearer "+t.token)
49		r.Header.Set("User-Agent", userAgent)
50		if r.Header.Get("Accept") == "" {
51			r.Header.Set("Accept", "application/json")
52		}
53		resp, err := t.base.RoundTrip(r)
54		if err != nil {
55			return nil, fmt.Errorf("round trip: %w", err)
56		}
57		return resp, nil
58	}
