200	// CheckResponse returns an error if the response status code indicates failure.
201	// For non-2xx responses, it reads and parses the error message from the body
202	// and returns it as an *HTTPError. The caller is responsible for closing resp.Body.
203	func CheckResponse(resp *http.Response) error {
204		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
205			return nil
206		}
207	
208		apiError := &HTTPError{StatusCode: resp.StatusCode}
209	
210		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
211		if err != nil {
212			return apiError
213		}
214	
215		var parsed ErrorResponse
216		if err := json.Unmarshal(body, &parsed); err == nil && strings.TrimSpace(parsed.Error) != "" {
217			apiError.Message = parsed.Error
218			return apiError
219		}
220	
221		if text := strings.TrimSpace(string(body)); text != "" {
222			apiError.Message = text
223		}
224		return apiError
